// ── Step builders ──────────────────────────────────────────────────────

func aimStepObserve(data AimPhaseData) aimCycleStepData {
	s := aimCycleStepData{
		Number:  1,
		Icon:    "lucide--eye",
		Label:   "Observe",
		CTAHref: "/strategies/" + data.InstanceID + "/aim/lra",
	}
	if data.HasLRA {
		s.Status = "done"
		s.Detail = "LRA " + data.LRALifecycleStage
		s.CTA = "View LRA"
	} else if data.HasNorthStar {
		// Foundation artifacts exist — AI can draft an LRA.
		s.Status = "active"
		s.Detail = "Start by capturing what's true today"
		s.CTA = "Create LRA"
		s.DraftAction = "/strategies/" + data.InstanceID + "/aim/draft-lra"
		s.DraftLabel = "AI draft"
	} else {
		// No foundation artifacts yet — LRA drafting is not possible.
		s.Status = "waiting"
		s.Detail = "Complete North Star first"
		s.CTA = "Go to READY"
		s.CTAHref = "/strategies/" + data.InstanceID + "/ready"
	}
	return s
}

func aimStepAssess(data AimPhaseData) aimCycleStepData {
	s := aimCycleStepData{
		Number:  2,
		Icon:    "lucide--clipboard-check",
		Label:   "Assess",
		CTAHref: "/strategies/" + data.InstanceID + "/aim/assessment",
	}
	if !data.HasLRA {
		s.Status = "waiting"
		s.Detail = "Needs LRA first"
		s.CTA = "View report"
		return s
	}
	if data.HasAssessmentReport {
		s.Status = "done"
		s.Detail = "OKRs + assumptions scored"
		s.CTA = "View report"
	} else {
		s.Status = "active"
		s.Detail = "Score OKRs and test outcomes"
		s.CTA = "Create report"
		s.DraftAction = "/strategies/" + data.InstanceID + "/aim/draft-assessment"
	}
	return s
}

func aimStepDecide(data AimPhaseData) aimCycleStepData {
	s := aimCycleStepData{
		Number:  3,
		Icon:    "lucide--sliders-horizontal",
		Label:   "Decide",
		CTAHref: "/strategies/" + data.InstanceID + "/aim/calibration",
	}
	if !data.HasAssessmentReport {
		s.Status = "waiting"
		s.Detail = "Needs assessment first"
		s.CTA = "View memo"
		return s
	}
	if data.HasCalibration && calibrationDecisionIsReal(data.LatestCalibrationDecision) {
		s.Status = "done"
		s.Detail = calibrationDecisionLabel(data.LatestCalibrationDecision)
		s.CTA = "View memo"
	} else if data.HasCalibration {
		// Stub memo exists (pending_assessment) — visible but incomplete.
		s.Status = "active"
		s.Detail = "Memo exists — decision still needed"
		s.CTA = "Complete memo"
		s.DraftAction = "/strategies/" + data.InstanceID + "/aim/draft-calibration"
	} else {
		s.Status = "active"
		s.Detail = "Persevere, pivot, or stop?"
		s.CTA = "Write memo"
		s.DraftAction = "/strategies/" + data.InstanceID + "/aim/draft-calibration"
	}
	return s
}

func aimStepAdapt(data AimPhaseData) aimCycleStepData {
	s := aimCycleStepData{
		Number:  4,
		Icon:    "lucide--refresh-cw",
		Label:   "Adapt",
		CTAHref: "/strategies/" + data.InstanceID + "/aim/versions",
	}
	if !data.HasCalibration || !calibrationDecisionIsReal(data.LatestCalibrationDecision) {
		s.Status = "waiting"
		s.Detail = "Needs calibration decision first"
		s.CTA = "View versions"
		return s
	}
	if data.VersionCount > 0 {
		s.Status = "done"
		s.Detail = strconv.Itoa(data.VersionCount) + " version(s) published"
		s.CTA = "View versions"
	} else {
		// Calibration decided but not yet applied — primary action is to
		// generate strategy patches, then publish a version.
		s.Status = "active"
		s.CTAHref = "/strategies/" + data.InstanceID + "/aim/versions"
		s.Detail = "AI rewrites strategy_formula and roadmap from calibration decision"
		s.CTA = "View versions"
		s.DraftAction = "/strategies/" + data.InstanceID + "/aim/apply-calibration"
		if data.HasSkillExecutor {
			s.DraftLabel = "AI strategy rewrite"
		} else {
			s.DraftLabel = "Apply calibration patches"
		}
	}
	return s
}

// ── Step style helpers ─────────────────────────────────────────────────

func aimStepBorderClass(status string) string {
	switch status {
	case "done":
		return "border-success/20 bg-success/5"
	case "active":
		return "border-primary/30 bg-primary/5"
	default:
		return "border-base-content/10 bg-base-100 opacity-60"
	}
}

func aimStepCircleClass(status string) string {
	switch status {
	case "done":
		return "bg-success text-success-content"
	case "active":
		return "bg-primary text-primary-content"
	default:
		return "bg-base-content/10 text-base-content/40"
	}
}

func aimStepIconClass(status string) string {
	switch status {
	case "done":
		return "text-success"
	case "active":
		return "text-primary"
	default:
		return "text-base-content/30"
	}
}

func aimStepLabelClass(status string) string {
	switch status {
	case "done":
		return "text-success"
	case "active":
		return "text-base-content"
	default:
		return "text-base-content/40"
	}
}

func aimStepCTAClass(status string) string {
	switch status {
	case "done":
		return "text-success/70"
	case "active":
		return "text-primary"
	default:
		return "text-base-content/30"
	}
}

// aimAutomationHint returns a short string describing when the next cycle will be
// proposed automatically, for display in the stepper header.
func aimAutomationHint(data AimPhaseData) string {
	days := data.TriggerDays
	if days <= 0 {
		days = 90
	}
	sigs := data.TriggerSignalThreshold
	if sigs <= 0 {
		sigs = 3
	}
	if data.DaysSinceAssessment < 0 {
		// No prior assessment
		return fmt.Sprintf("Cycle proposed automatically every %d days or when %d+ critical signals accumulate", days, sigs)
	}
	remaining := days - data.DaysSinceAssessment
	if remaining <= 0 {
		return "Time-based cycle trigger is active — proposal will be created automatically"
	}
	return fmt.Sprintf("Next cycle proposed automatically in ~%d days or when %d+ critical signals accumulate", remaining, sigs)
}

// calibrationDecisionIsReal returns true only when the calibration memo
// contains a real decision (persevere, pivot, pull_the_plug). A memo with
// decision "pending_assessment" or empty is a scaffold stub — it should not
// unlock the Adapt step.
func calibrationDecisionIsReal(decision string) bool {
	switch decision {
	case "persevere", "pivot", "pull_the_plug":
		return true
	default:
		return false
	}
}

func calibrationDecisionBadgeClass(decision string) string {
	switch decision {
	case "persevere":
		return "badge-success"
	case "pivot":
		return "badge-warning"
	case "pull_the_plug":
		return "badge-error"
	default:
		return "badge-ghost"
	}
}

